import{_ as s,C as r,o as e,c as o,a2 as i,b as l,w as n,a as d,E as c,a3 as g}from"./chunks/framework.CRkDNIZq.js";const _=JSON.parse('{"title":"14.2 Architecture Styles & Ingestion Pipes","description":"","frontmatter":{},"headers":[],"relativePath":"system-design/14.2-architecture-styles.md","filePath":"system-design/14.2-architecture-styles.md"}'),h={name:"system-design/14.2-architecture-styles.md"};function u(p,t,y,m,f,b){const a=r("Mermaid");return e(),o("div",null,[t[1]||(t[1]=i('<h1 id="_14-2-architecture-styles-ingestion-pipes" tabindex="-1">14.2 Architecture Styles &amp; Ingestion Pipes <a class="header-anchor" href="#_14-2-architecture-styles-ingestion-pipes" aria-label="Permalink to &quot;14.2 Architecture Styles &amp; Ingestion Pipes&quot;">​</a></h1><h2 id="_1-what-it-is-in-plain-words" tabindex="-1">1. What It Is in Plain Words <a class="header-anchor" href="#_1-what-it-is-in-plain-words" aria-label="Permalink to &quot;1. What It Is in Plain Words&quot;">​</a></h2><p>Architecture style defines the coarse-grained structural organization of software: whether all components run in a single deployable unit (Monolith), separated domain boundaries within one deployable (Modular Monolith), independent network-separated services (Microservices), or ephemeral on-demand compute (Serverless).</p><hr><h2 id="_2-how-this-project-uses-it" tabindex="-1">2. How This Project Uses It <a class="header-anchor" href="#_2-how-this-project-uses-it" aria-label="Permalink to &quot;2. How This Project Uses It&quot;">​</a></h2><p>In <code>backend/src/</code>:</p><ul><li><strong>Current Style</strong>: <strong>Modular Monolith</strong>.</li><li>Distinct business modules (<code>metering/</code>, <code>rating/</code>, <code>invoicing/</code>, <code>models/ledger.py</code>, <code>payments/</code>) are strictly isolated with explicit domain interfaces, while sharing an asynchronous PostgreSQL database connection pool.</li><li>This style was chosen because financial billing operations—such as finalizing an invoice and posting double-entry ledger entries—require ACID transaction guarantees that cannot be maintained across distributed microservices without complex two-phase commit protocols.</li></ul>',7)),(e(),l(g,null,{default:n(()=>[c(a,{id:"mermaid-33",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20subgraph%20Monolith%5B%22Modular%20Monolith%20Architecture%22%5D%0A%20%20%20%20%20%20%20%20API%5Bapi%2Fapp.py%3A%20REST%20Endpoints%5D%0A%20%20%20%20%20%20%20%20Mtr%5Bmetering%2Fingestion.py%5D%0A%20%20%20%20%20%20%20%20Rtg%5Brating%2Fengine.py%5D%0A%20%20%20%20%20%20%20%20Inv%5Binvoicing%2Fmanager.py%5D%0A%20%20%20%20%20%20%20%20Led%5Bmodels%2Fledger.py%5D%0A%20%20%20%20%20%20%20%20Pay%5Bpayments%2Fcollections.py%5D%0A%20%20%20%20end%0A%0A%20%20%20%20API%20--%3E%20Mtr%0A%20%20%20%20API%20--%3E%20Inv%0A%20%20%20%20API%20--%3E%20Pay%0A%20%20%20%20Inv%20--%3E%20Rtg%0A%20%20%20%20Inv%20--%3E%20Led%0A%20%20%20%20Pay%20--%3E%20Led%0A%20%20%20%20Led%20--%3E%20DB%5B(PostgreSQL%2016%20ACID%20Database)%5D%0A"})]),fallback:n(()=>[...t[0]||(t[0]=[d(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=i('<hr><h2 id="_3-comparison-of-architecture-styles" tabindex="-1">3. Comparison of Architecture Styles <a class="header-anchor" href="#_3-comparison-of-architecture-styles" aria-label="Permalink to &quot;3. Comparison of Architecture Styles&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Factor</th><th style="text-align:left;">Modular Monolith [This Project]</th><th style="text-align:left;">Distributed Microservices</th><th style="text-align:left;">Serverless (AWS Lambda)</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Transactional Integrity</strong></td><td style="text-align:left;"><strong>Strict ACID across all tables</strong></td><td style="text-align:left;">Eventual consistency / 2PC</td><td style="text-align:left;">Eventual consistency</td></tr><tr><td style="text-align:left;"><strong>Operational Overhead</strong></td><td style="text-align:left;"><strong>Low (single container/process)</strong></td><td style="text-align:left;">High (Kubernetes, mesh, tracing)</td><td style="text-align:left;">Moderate (Cold starts, IAM)</td></tr><tr><td style="text-align:left;"><strong>Deployment Complexity</strong></td><td style="text-align:left;"><strong>Atomic single-command deploy</strong></td><td style="text-align:left;">Independent multi-pipeline</td><td style="text-align:left;">Independent function deploys</td></tr><tr><td style="text-align:left;"><strong>Network Latency</strong></td><td style="text-align:left;"><strong>In-memory local function calls</strong></td><td style="text-align:left;">HTTP / gRPC hop latency</td><td style="text-align:left;">Cold start + network latency</td></tr><tr><td style="text-align:left;"><strong>Scaling Flexibility</strong></td><td style="text-align:left;">Scale entire process</td><td style="text-align:left;">Independent service scaling</td><td style="text-align:left;">Infinite autoscaling</td></tr></tbody></table><ul><li><strong>Why I Used Modular Monolith</strong>: Preserves ACID transactions during billing reconciliation without distributed lock complexity [CONFIRM WITH DEVELOPER].</li><li><strong>Why I Did Not Use Microservices</strong>: Splitting the ledger from invoicing would require a distributed Saga pattern, drastically increasing failure modes.</li></ul><hr><h2 id="_4-what-breaks-first-at-scale" tabindex="-1">4. What Breaks First at Scale <a class="header-anchor" href="#_4-what-breaks-first-at-scale" aria-label="Permalink to &quot;4. What Breaks First at Scale&quot;">​</a></h2><p>At 100x scale, high-frequency telemetry ingestion begins competing with heavy end-of-month aggregation queries for CPU and connection pool slots.</p><ul><li><strong>Senior Engineer Remediation</strong>: Extract <code>metering/ingestion.py</code> into a dedicated high-throughput <em>Ingestion Microservice</em> communicating asynchronously with the billing core via Kafka.</li></ul><hr><h2 id="_5-30-second-interview-answer" tabindex="-1">5. 30-Second Interview Answer <a class="header-anchor" href="#_5-30-second-interview-answer" aria-label="Permalink to &quot;5. 30-Second Interview Answer&quot;">​</a></h2><blockquote><p>&quot;I architected 19-Usage-Billing-Engine as a modular monolith. This gives us clear domain separation between metering, rating, and invoicing while allowing ledger entries and invoice finalizations to execute within the same atomic ACID database transaction. Under extreme scale, I would decouple the telemetry ingestion pipeline into an independent event streaming service while keeping the financial accounting core strictly transactional.&quot;</p></blockquote>',11))])}const x=s(h,[["render",u]]);export{_ as __pageData,x as default};
